import hashlib
from contextlib import asynccontextmanager
from datetime import datetime, timedelta
from uuid import uuid4

import httpx
from fastapi import Depends, FastAPI, Header, HTTPException, status
from sqlalchemy.orm import Session

from app.config import settings
from app.db import Base, engine, get_db
from app.models import PaymentMethodToken, PaymentSession
from app.schemas import ConfirmIn, PaymentSessionIn, TokenizeIn


def utcnow() -> datetime:
    return datetime.utcnow()


def normalize_currency(value: str) -> str:
    return value.lower().strip()


def card_brand(card_number: str) -> str:
    if card_number.startswith("4"):
        return "visa"
    if card_number[:2] in {"51", "52", "53", "54", "55"}:
        return "mastercard"
    if card_number[:2] in {"34", "37"}:
        return "amex"
    return "card"


def card_fingerprint(card_number: str) -> str:
    return hashlib.sha256(card_number.encode("utf-8")).hexdigest()


def session_response(row: PaymentSession) -> dict:
    return {
        "session_id": row.session_id,
        "merchant_id": row.merchant_id,
        "user_id": row.user_id,
        "cart_id": row.cart_id,
        "order_id": row.order_id,
        "amount": row.amount,
        "currency": row.currency,
        "description": row.description,
        "metadata": row.metadata_json or {},
        "capture": row.capture,
        "status": row.status,
        "payment_id": row.payment_id,
        "failure_message": row.failure_message,
        "expires_at": row.expires_at.isoformat(),
        "confirmed_at": row.confirmed_at.isoformat() if row.confirmed_at else None,
        "created_at": row.created_at.isoformat(),
        "updated_at": row.updated_at.isoformat(),
    }


def token_response(row: PaymentMethodToken) -> dict:
    return {
        "payment_method_token": row.payment_method_token,
        "merchant_id": row.merchant_id,
        "user_id": row.user_id,
        "brand": row.brand,
        "last4": row.last4,
        "status": row.status,
        "expires_at": row.expires_at.isoformat(),
        "created_at": row.created_at.isoformat(),
    }


def get_owned_session(db: Session, session_id: str, merchant_id: str, user_id: str) -> PaymentSession:
    row = (
        db.query(PaymentSession)
        .filter(
            PaymentSession.session_id == session_id,
            PaymentSession.merchant_id == merchant_id,
            PaymentSession.user_id == user_id,
        )
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="Payment session not found")
    return row


def get_owned_token(db: Session, token: str, merchant_id: str, user_id: str) -> PaymentMethodToken:
    row = (
        db.query(PaymentMethodToken)
        .filter(
            PaymentMethodToken.payment_method_token == token,
            PaymentMethodToken.merchant_id == merchant_id,
            PaymentMethodToken.user_id == user_id,
        )
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="Payment method token not found")
    return row


@asynccontextmanager
async def lifespan(app: FastAPI):
    Base.metadata.create_all(bind=engine)
    app.state.http = httpx.AsyncClient(timeout=20.0)
    yield
    await app.state.http.aclose()


app = FastAPI(title=settings.service_name, lifespan=lifespan)


@app.get("/health")
async def health():
    return {"status": "ok"}


@app.get("/config")
async def config(x_merchant_id: str = Header(...)):
    return {
        "merchant_id": x_merchant_id,
        "supported_methods": ["card"],
        "three_ds": False,
        "hosted_checkout": True,
    }


@app.post("/payment_sessions")
async def create_payment_session(
    payload: PaymentSessionIn,
    x_merchant_id: str = Header(...),
    x_user_id: str = Header(...),
    x_user_email: str = Header(""),
    db: Session = Depends(get_db),
):
    row = PaymentSession(
        session_id=f"ps_{uuid4().hex[:18]}",
        merchant_id=x_merchant_id,
        user_id=x_user_id,
        user_email=x_user_email or None,
        cart_id=payload.cart_id,
        order_id=payload.order_id,
        amount=payload.amount,
        currency=normalize_currency(payload.currency),
        description=payload.description,
        metadata_json=payload.metadata or {},
        capture=payload.capture,
        status="created",
        expires_at=utcnow() + timedelta(minutes=settings.checkout_session_ttl_minutes),
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    return session_response(row)


@app.get("/payment_sessions/{session_id}")
async def get_payment_session(
    session_id: str,
    x_merchant_id: str = Header(...),
    x_user_id: str = Header(...),
    db: Session = Depends(get_db),
):
    row = get_owned_session(db, session_id, x_merchant_id, x_user_id)
    if row.expires_at < utcnow() and row.status == "created":
        row.status = "expired"
        row.updated_at = utcnow()
        db.commit()
        db.refresh(row)
    return session_response(row)


@app.post("/payment_methods/tokenize")
async def tokenize(
    payload: TokenizeIn,
    x_merchant_id: str = Header(...),
    x_user_id: str = Header(...),
    x_user_email: str = Header(""),
    db: Session = Depends(get_db),
):
    token = PaymentMethodToken(
        payment_method_token=f"pm_{uuid4().hex[:18]}",
        merchant_id=x_merchant_id,
        user_id=x_user_id,
        user_email=x_user_email or None,
        brand=card_brand(payload.card_number),
        last4=payload.card_number[-4:],
        fingerprint=card_fingerprint(payload.card_number),
        card_number=payload.card_number,
        exp_month=payload.exp_month,
        exp_year=payload.exp_year,
        cvc=payload.cvc,
        status="active",
        expires_at=utcnow() + timedelta(minutes=settings.payment_method_ttl_minutes),
    )
    db.add(token)
    db.commit()
    db.refresh(token)
    return token_response(token)


@app.post("/payment_intents/confirm")
async def confirm_payment_intent(
    payload: ConfirmIn,
    x_merchant_id: str = Header(...),
    x_user_id: str = Header(...),
    x_user_email: str = Header(""),
    db: Session = Depends(get_db),
):
    session_row = get_owned_session(db, payload.session_id, x_merchant_id, x_user_id)
    token_row = get_owned_token(db, payload.payment_method_token, x_merchant_id, x_user_id)

    now = utcnow()

    if session_row.expires_at < now:
        session_row.status = "expired"
        session_row.updated_at = now
        db.commit()
        raise HTTPException(status_code=400, detail="Payment session expired")

    if token_row.expires_at < now or token_row.status != "active":
        if token_row.status == "active" and token_row.expires_at < now:
            token_row.status = "expired"
            db.commit()
        raise HTTPException(status_code=400, detail="Payment method token invalid or expired")

    if session_row.status not in {"created", "failed"}:
        return {
            "session": session_response(session_row),
            "message": "Session already processed",
        }

    session_row.status = "processing"
    session_row.failure_message = None
    session_row.updated_at = now
    db.commit()

    upstream_payload = {
        "amount": session_row.amount,
        "currency": session_row.currency,
        "customer": {
            "email": x_user_email or session_row.user_email or f"{x_user_id}@example.local",
            "name": x_user_id or "Hosted Checkout Customer",
        },
        "card": {
            "number": token_row.card_number,
            "exp_month": token_row.exp_month,
            "exp_year": token_row.exp_year,
            "cvc": token_row.cvc,
        },
        "order_id": session_row.order_id or session_row.cart_id,
        "description": session_row.description,
        "metadata": {
            **(session_row.metadata_json or {}),
            "checkout_session_id": session_row.session_id,
            "payment_method_token": token_row.payment_method_token,
            "channel": "hosted_checkout",
        },
        "capture": session_row.capture,
    }

    headers = {
        "x-merchant-id": x_merchant_id,
        "Idempotency-Key": f"confirm:{session_row.session_id}",
    }

    try:
        response = await app.state.http.post(
            f"{settings.payment_service_url}/payment_intents",
            json=upstream_payload,
            headers=headers,
        )
    except httpx.HTTPError as exc:
        session_row.status = "failed"
        session_row.failure_message = f"Payment service unreachable: {exc}"
        session_row.updated_at = utcnow()
        db.commit()
        raise HTTPException(status_code=502, detail="Payment service unavailable") from exc

    if response.status_code >= 400:
        detail = response.text
        try:
            detail = response.json()
        except Exception:
            pass

        session_row.status = "failed"
        session_row.failure_message = str(detail)
        session_row.updated_at = utcnow()
        db.commit()

        raise HTTPException(
            status_code=response.status_code,
            detail=detail,
        )

    payment_data = response.json()
    session_row.payment_id = payment_data.get("payment_id")
    session_row.status = payment_data.get("status", "authorized").lower()
    session_row.confirmed_at = utcnow()
    session_row.updated_at = utcnow()

    token_row.status = "consumed"
    token_row.used_at = utcnow()

    db.commit()
    db.refresh(session_row)

    return {
        "session": session_response(session_row),
        "payment": payment_data,
    }
